<?php if ( ! defined( 'ABSPATH' ) ) { exit; } ?>
<div class="ps-coa-history-categories"><p><?php esc_html_e( 'Laboratory Categories Reported', 'pepselect-coa-archive' ); ?></p><ul><?php foreach ( $report['qc_strip_rows'] as $row ) : $failed = ! empty( $row['reported'] ) && empty( $row['status']['success'] ); ?><li class="<?php echo ! $row['reported'] ? 'is-neutral' : ( $failed ? 'is-failed' : 'is-success' ); ?>"><span aria-hidden="true"><?php echo ! $row['reported'] ? '—' : ( $failed ? '!' : '✓' ); ?></span><strong><?php echo esc_html( $row['short_label'] ); ?></strong><small><?php echo esc_html( $row['reported'] ? $row['detail'] : '--' ); ?></small></li><?php endforeach; ?></ul></div>
